CREATE TABLE IF NOT EXISTS reward_campaign(id BIGINT AUTO_INCREMENT PRIMARY KEY,reward_no VARCHAR(40) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,target VARCHAR(20) NOT NULL,scope VARCHAR(20) NOT NULL,users TEXT,planned_count INT,amount_mode VARCHAR(20) NOT NULL,amount BIGINT,min_amount BIGINT,max_amount BIGINT,total_amount BIGINT,status VARCHAR(20) NOT NULL,send_mode VARCHAR(20),send_at DATETIME,created_at DATETIME,remark VARCHAR(500),operator_id BIGINT,operator_name VARCHAR(100),actual_count INT DEFAULT 0,actual_amount BIGINT DEFAULT 0,failed_count INT DEFAULT 0,error_message VARCHAR(1000),KEY idx_reward_status_send(status,send_at),KEY idx_reward_created(created_at),KEY idx_reward_target(target)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS reward_grant(id BIGINT AUTO_INCREMENT PRIMARY KEY,campaign_id BIGINT NOT NULL,user_id BIGINT NOT NULL,user_role VARCHAR(20),amount BIGINT NOT NULL,status VARCHAR(20),granted_at DATETIME,error_message VARCHAR(500),UNIQUE KEY uk_reward_grant_user(campaign_id,user_id),KEY idx_reward_grant_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS reward_fund_account(id BIGINT PRIMARY KEY,balance BIGINT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS reward_fund_flow(id BIGINT AUTO_INCREMENT PRIMARY KEY,fund_account_id BIGINT NOT NULL,direction VARCHAR(20) NOT NULL,amount BIGINT NOT NULL,balance_after BIGINT NOT NULL,campaign_id BIGINT NOT NULL,remark VARCHAR(500),created_at DATETIME NOT NULL,UNIQUE KEY uk_reward_fund_flow_campaign(campaign_id),KEY idx_reward_fund_flow_campaign(campaign_id),KEY idx_reward_fund_flow_created(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO reward_fund_account(id,balance) VALUES(1,0) ON DUPLICATE KEY UPDATE id=VALUES(id);
